def _is_empty_column_selection(column):
    """
    Return True if the column selection is empty (empty list or all-False
    boolean array).

    """
    if (
        hasattr(column, "dtype")
        # Not necessarily a numpy dtype, can be a pandas dtype as well
        and isinstance(column.dtype, np.dtype)
        and np.issubdtype(column.dtype, np.bool_)
    ):
        return not column.any()
    elif hasattr(column, "__len__"):
        return len(column) == 0 or (
            all(isinstance(col, bool) for col in column) and not any(column)
        )
    else:
        return False

def downcast_intp_index(arr):
    """
    Down-cast index array to np.intp dtype if it is of a larger dtype.

    Raise an error if the array contains a value that is too large for
    intp.
    """
    if arr.dtype.itemsize > np.dtype(np.intp).itemsize:
        if arr.size == 0:
            return arr.astype(np.intp)
        maxval = arr.max()
        minval = arr.min()
        if maxval > np.iinfo(np.intp).max or minval < np.iinfo(np.intp).min:
            raise ValueError("Cannot deal with arrays with indices larger "
                             "than the machine maximum address size "
                             "(e.g. 64-bit indices on 32-bit machine).")
        return arr.astype(np.intp)
    return arr

def _map_prop_with_hue(self, name, value, fallback, plot_kws):
