def get(cls, code: str) -> Locale:
        """Returns the Locale for the given locale code.

        If it is not supported, we raise an exception.
        """
        if code not in cls._cache:
            assert code in _supported_locales
            translations = _translations.get(code, None)
            if translations is None:
                locale: Locale = CSVLocale(code, {})
            elif _use_gettext:
                locale = GettextLocale(code, translations)
            else:
                locale = CSVLocale(code, translations)
            cls._cache[code] = locale
        return cls._cache[code]

def _validate_marker_names(expr: Expression, config: Config) -> None:
    """Validate that all marker names in the expression are registered.

    Only validates when strict_markers is enabled.
    """
    strict_markers = config.getini("strict_markers")
    if strict_markers is None:
        strict_markers = config.getini("strict")
    if not strict_markers:
        return

    registered_markers = {m.name for m in config._iter_registered_markers()}

    unknown_markers = expr.idents() - registered_markers
    if unknown_markers:
        unknown_str = ", ".join(sorted(unknown_markers))
        raise UsageError(
            f"Unknown marker(s) in '-m' expression: {unknown_str}. "
            "Use 'pytest --markers' to see available markers."
        )

def radius(self):
        """Return radius of the subcluster"""
        # Because of numerical issues, this could become negative
        sq_radius = self.squared_sum_ / self.n_samples_ - self.sq_norm_
        return sqrt(max(0, sq_radius))

def _reduced_density(self, matrix, qubit, **options):
        """Compute the reduced density matrix by tracing out one qubit.
           The qubit argument should be of type Python int, since it is used
           in bit operations
        """
        def find_index_that_is_projected(j, k, qubit):
            bit_mask = 2**qubit - 1
            return ((j >> qubit) << (1 + qubit)) + (j & bit_mask) + (k << qubit)

        old_matrix = represent(matrix, **options)
        old_size = old_matrix.cols
        #we expect the old_size to be even
        new_size = old_size//2
        new_matrix = Matrix().zeros(new_size)

        for i in range(new_size):
            for j in range(new_size):
                for k in range(2):
                    col = find_index_that_is_projected(j, k, qubit)
                    row = find_index_that_is_projected(i, k, qubit)
                    new_matrix[i, j] += old_matrix[row, col]

        return new_matrix

