def classify_libs(libs):
    """Classify libraries into shared libs, stdlib extensions, and package extensions"""
    shared = []
    stdlib = []
    extensions = []
    for lib in libs:
        if '/lib-dynload/' in lib:
            stdlib.append(lib)
        elif '/site-packages/' in lib or re.search(r'/build-[^/]*-install/', lib):
            extensions.append(lib)
        else:
            shared.append(lib)
    return {
        'shared': sorted(shared, key=strip_prefix),
        'stdlib': sorted(stdlib, key=strip_prefix),
        'extensions': sorted(extensions, key=strip_prefix),
    }

def _looks_like_import_path(value: str) -> bool:
    """Return True if **value** looks like a valid Python import path or False
    otherwise."""
    if not value:
        return False
    if any(c.isspace() for c in value):
        return False
    allowed_chars = set(
        "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_."
    )
    if any(c not in allowed_chars for c in value):
        return False
    if value[0] == "." or value[-1] == ".":
        return False
    parts = value.split(".")
    if any(part == "" for part in parts):
        return False
    return all(part.isidentifier() for part in parts)

