        raise ValueError(
            f"number of poles is {len(poles)} but you should provide {A.shape[0]}"
        )
    r = np.linalg.matrix_rank(B)
    for p in poles:
        if sum(p == poles) > r:
            raise ValueError("at least one of the requested pole is repeated "
                             "more than rank(B) times")
    # Choose update method
    update_loop = _YT_loop
    if method not in ('KNV0','YT'):
        raise ValueError("The method keyword must be one of 'YT' or 'KNV0'")

    if method == "KNV0":
        update_loop = _KNV0_loop
        if not all(np.isreal(poles)):
            raise ValueError("Complex poles are not supported by KNV0")

    if maxiter < 1:
        raise ValueError("maxiter must be at least equal to 1")

    # We do not check rtol <= 0 as the user can use a negative rtol to
    # force maxiter iterations
    if rtol > 1:
        raise ValueError("rtol can not be greater than 1")

    return update_loop, poles

def copy_cache(
    cache: t.MutableMapping[tuple["weakref.ref[BaseLoader]", str], "Template"] | None,
) -> t.MutableMapping[tuple["weakref.ref[BaseLoader]", str], "Template"] | None:
    """Create an empty copy of the given cache."""
    if cache is None:
        return None

    if type(cache) is dict:  # noqa E721
        return {}

    return LRUCache(cache.capacity)

def _permutation_test_iv(data, statistic, permutation_type, vectorized,
                         n_resamples, batch, alternative, axis, rng):
    """Input validation for `permutation_test`."""
    axis_int = int(axis)
    if axis != axis_int:
        raise ValueError("`axis` must be an integer.")

    permutation_types = {'samples', 'pairings', 'independent'}
    permutation_type = permutation_type.lower()
    if permutation_type not in permutation_types:
        raise ValueError(f"`permutation_type` must be in {permutation_types}.")

    if vectorized not in {True, False, None}:
        raise ValueError("`vectorized` must be `True`, `False`, or `None`.")

    if vectorized is None:
        vectorized = 'axis' in inspect.signature(statistic).parameters

    message = "`data` must be a tuple containing at least two samples"
    try:
        if len(data) < 2 and permutation_type == 'independent':
            raise ValueError(message)
    except TypeError:
        raise TypeError(message)

    xp = array_namespace(*data)

    if not vectorized:
        if not is_numpy(xp):
            message = (f"When using array library {xp.__name__}, `func` must be "
                       "vectorized and accept argument `axis`.")
            raise TypeError(message)

        statistic = _vectorize_statistic(statistic)

    data = _broadcast_arrays(data, axis, xp=xp)
    data_iv = []
    for sample in data:
        sample = xpx.atleast_nd(sample, ndim=1)
        if sample.shape[axis] <= 1:
            raise ValueError("each sample in `data` must contain two or more "
                             "observations along `axis`.")
        sample = xp.moveaxis(sample, axis_int, -1)
        data_iv.append(sample)

    n_resamples_int = (int(n_resamples) if not math.isinf(n_resamples)
                       else xp.inf)
    if n_resamples != n_resamples_int or n_resamples_int <= 0:
        raise ValueError("`n_resamples` must be a positive integer.")

    if batch is None:
        batch_iv = batch
    else:
        batch_iv = int(batch)
        if batch != batch_iv or batch_iv <= 0:
            raise ValueError("`batch` must be a positive integer or None.")

    alternatives = {'two-sided', 'greater', 'less'}
    alternative = alternative.lower()
    if alternative not in alternatives:
        raise ValueError(f"`alternative` must be in {alternatives}")

    rng = check_random_state(rng)

    float_dtype = xp_result_type(*data_iv, force_floating=True, xp=xp)

    return (data_iv, statistic, permutation_type, vectorized, n_resamples_int,
            batch_iv, alternative, axis_int, rng, float_dtype, xp)

def mod_int(
        arr: pa.Array | pa.ChunkedArray, modulo: int
    ) -> pa.Array | pa.ChunkedArray:
        """
        Compute ``arr % modulo`` for a non-negative int (chunked) array.

        PyArrow lacks a modulo kernel, so emulate it with divide/multiply/subtract.
        TODO: revisit once Arrow has a modulo kernel.
        """
        quotient = pc.divide(arr, modulo)
        return pc.subtract(arr, pc.multiply(quotient, modulo))

def get_all_dict(module):
    """Return a copy of the __all__ dict with irrelevant items removed."""
    if hasattr(module, "__all__"):
        all_dict = copy.deepcopy(module.__all__)
    else:
        all_dict = copy.deepcopy(dir(module))
        all_dict = [name for name in all_dict
                    if not name.startswith("_")]
    for name in ['absolute_import', 'division', 'print_function']:
        try:
            all_dict.remove(name)
        except ValueError:
            pass

    # Modules are almost always private; real submodules need a separate
    # run of refguide_check.
    all_dict = [name for name in all_dict
                if not inspect.ismodule(getattr(module, name, None))]

    deprecated = []
    not_deprecated = []
    for name in all_dict:
        f = getattr(module, name, None)
        if callable(f) and is_deprecated(f):
            deprecated.append(name)
        else:
            not_deprecated.append(name)

    others = (set(dir(module))
              .difference(set(deprecated))
              .difference(set(not_deprecated)))

    return not_deprecated, deprecated, others

def _sha256(path):
    """Calculate the sha256 hash of the file at path."""
    sha256hash = hashlib.sha256()
    chunk_size = 8192
    with open(path, "rb") as f:
        while True:
            buffer = f.read(chunk_size)
            if not buffer:
                break
            sha256hash.update(buffer)
    return sha256hash.hexdigest()

def sanitize_url(url, mask='*' * 8):
    """Sanitize URL, masking passwords.

    Supports:
    - Standard single-server URLs (e.g. ``redis://:secret@localhost:6379/0``)
    - Passwords containing separators such as semicolons or commas
    - Multi-server URLs with shared scheme (e.g. ``cache+memcached://user:secret@s1:11211;s2:11211/``)
    - Redis Sentinel multi-node URLs (e.g. ``sentinel://:secret@h1:26379;sentinel://:secret@h2:26379/0``
      or ``sentinel://:secret@h1:26379;h2:26379/0``)
    - URLs with query strings containing semicolons (e.g. ``redis://user:secret@localhost:6379?a=1;b=2``)

    Fails closed on malformed URLs to prevent credential leakage.
    """
    if not url or not isinstance(url, str):
        return url

    def _mask_uinfo(uinfo):
        if ':' in uinfo:
            user, _, _ = uinfo.partition(':')
            return f'{user}:{mask}'
        return uinfo

    try:
        if '://' not in url:
            return url

        # If it is a semicolon-separated list of full URLs (e.g. sentinel://...;sentinel://...)
        parts = url.split(';')
        if len(parts) > 1 and any('://' in p for p in parts[1:]):
            return ';'.join(sanitize_url(p.strip(), mask=mask) for p in parts)

        scheme, _, rest = url.partition('://')

        # Separate authority from path/query/fragment
        idx = len(rest)
        for sep in ('/', '?', '#'):
            pos = rest.find(sep)
            if pos != -1 and pos < idx:
                idx = pos
        authority = rest[:idx]
        tail = rest[idx:]

        if '@' not in authority:
            # No credentials in authority: clean empty chunks if multi-host
            host_sep = ';' if ';' in authority else (',' if ',' in authority else None)
            if host_sep:
                h_list = [h.strip() for h in authority.split(host_sep) if h.strip()]
                return f'{scheme}://{host_sep.join(h_list)}{tail}'
            return f'{scheme}://{authority}{tail}'

        uinfo, _, host_part = authority.rpartition('@')

        server_sep = ';' if ';' in authority else (',' if ',' in authority else None)

        is_multiserver = False
        if server_sep:
            raw_chunks = [c.strip() for c in authority.split(server_sep) if c.strip()]
            if len(raw_chunks) > 1:
                has_corrupt_chunk = any(c.startswith(':') for c in raw_chunks if '@' not in c)
                has_at_without_colon = any(':' not in c.rpartition('@')[0] for c in raw_chunks if '@' in c)
                if not has_corrupt_chunk and not has_at_without_colon:
                    is_multiserver = True

        if not is_multiserver:
            if authority.count('@') > 1 and ':' not in uinfo:
                return f'{scheme}://{mask}@{host_part}{tail}'
            sanitized_uinfo = _mask_uinfo(uinfo)
            return f'{scheme}://{sanitized_uinfo}@{host_part}{tail}'

        servers = [c.strip() for c in authority.split(server_sep) if c.strip()]
        sanitized_servers = []
        for s in servers:
            if '@' in s:
                u, _, h = s.rpartition('@')
                sanitized_servers.append(f'{_mask_uinfo(u)}@{h}')
            else:
                sanitized_servers.append(s)

        sanitized_authority = server_sep.join(sanitized_servers)
        return f'{scheme}://{sanitized_authority}{tail}'

    except Exception:
        if isinstance(url, str) and '@' in url and '://' in url:
            import re
            return re.sub(r'(://[^:@/]*:)([^@/]*)(@)', r'\g<1>' + mask + r'\3', url)
        return '<unparsable url>'

