def _is_int_type(x):
    """
    Check if input is of a scalar integer type (so ``5`` and ``array(5)`` will
    pass, while ``5.0`` and ``array([5])`` will fail.
    """
    try:
        operator.index(x)
    except TypeError:
        return False
    else:
        return True

def equals(self, other: Any) -> bool:
        """
        Determines if two Index objects contain the same elements.
        """
        if self.is_(other):
            return True

        if not isinstance(other, Index):
            return False
        elif other.dtype.kind in "iufc":
            return False
        elif not isinstance(other, type(self)):
            if other.dtype == object:
                # Use the cached inferred_type as a cheap pre-filter
                inferred = other.inferred_type
                compatible: tuple[str, ...]
                if self.dtype.kind == "M":
                    compatible = ("datetime", "datetime64", "date")
                elif self.dtype.kind == "m":
                    compatible = ("timedelta", "timedelta64")
                else:
                    compatible = ("period",)
                if inferred not in compatible:
                    return False
                converted = lib.maybe_convert_objects(
                    np.asarray(other), convert_non_numeric=True
                )
                converted = ensure_wrapped_if_datetimelike(converted)
                if isinstance(converted, type(self._data)):
                    other = type(self)._simple_new(converted)
                elif self.dtype.kind == "M" and inferred == "date":
                    # GH#65056
                    warnings.warn(
                        "Inferring datetime64 from data containing "
                        "datetime.date objects is deprecated. In a future "
                        "version, these will be left as object dtype. Use "
                        "pd.to_datetime to explicitly convert to datetime64.",
                        Pandas4Warning,
                        stacklevel=find_stack_level(),
                    )
                    try:
                        other = type(self)(other)
                    except (ValueError, TypeError, OverflowError):
                        return False
            elif isinstance(other.dtype, CategoricalDtype):
                other = cast("CategoricalIndex", other)
                cat_vals = np.asarray(other.categories)
                if cat_vals.dtype == object:
                    converted = lib.maybe_convert_objects(
                        cat_vals, convert_non_numeric=True
                    )
                    converted = ensure_wrapped_if_datetimelike(converted)
                else:
                    converted = ensure_wrapped_if_datetimelike(cat_vals)
                if isinstance(converted, type(self._data)):
                    try:
                        other = type(self)(other)
                    except (ValueError, TypeError, OverflowError):
                        return False
                elif (
                    self.dtype.kind == "M"
                    and cat_vals.dtype == object
                    and lib.infer_dtype(other.categories) == "date"
                ):
                    # GH#65056
                    warnings.warn(
                        "Inferring datetime64 from data containing "
                        "datetime.date objects is deprecated. In a "
                        "future version, these will be left as object "
                        "dtype. Use pd.to_datetime to explicitly "
                        "convert to datetime64.",
                        Pandas4Warning,
                        stacklevel=find_stack_level(),
                    )
                    try:
                        other = type(self)(other)
                    except (ValueError, TypeError, OverflowError):
                        return False

        if type(self) != type(other):
            return False
        elif self.dtype == other.dtype:
            return lib.array_equivalent_bytes(self.asi8, other.asi8)
        elif (self.dtype.kind == "M" and self.tz == other.tz) or self.dtype.kind == "m":  # type: ignore[attr-defined]
            # different units, otherwise matching
            try:
                # TODO: do this at the EA level?
                left, right = self._data._ensure_matching_resos(other._data)  # type: ignore[union-attr]
            except (OutOfBoundsDatetime, OutOfBoundsTimedelta):
                return False
            else:
                return lib.array_equivalent_bytes(left.view("i8"), right.view("i8"))
        return False

def _has_redundant_generator_parentheses(node: LN) -> bool:
    """Whether `node` adds parentheses around a parenthesized generator."""
    if (
        node.type != syms.atom
        or len(node.children) != 3
        or not is_lpar_token(node.children[0])
        or not is_rpar_token(node.children[-1])
    ):
        return False

    middle = node.children[1]
    return is_generator(middle) or _has_redundant_generator_parentheses(middle)

