def _format_values_line(fmt_values: list[str], max_width: int) -> str:
        """Format a list of values into a bracketed, width-respecting string."""
        if max_width == 0:
            return "[" + ", ".join(fmt_values) + "]"

        parts = ["["]
        cur_col_len = 1  # account for the opening bracket
        start = True
        for val in fmt_values:
            if not start:
                if cur_col_len + 2 + len(val) > max_width:
                    parts.append(",\n ")
                    cur_col_len = 1  # 1 space indent
                else:
                    parts.append(", ")
                    cur_col_len += 2
            parts.append(val)
            cur_col_len += len(val)
            start = False
        parts.append("]")
        return "".join(parts)

def _resolves_to_ipv6(host: str) -> bool:
    """Returns True if the system resolves host to an IPv6 address by default."""
    resolves_to_ipv6 = False
    try:
        for res in socket.getaddrinfo(host, None, socket.AF_UNSPEC):
            af, _, _, _, _ = res
            if af == socket.AF_INET6:
                resolves_to_ipv6 = True
    except socket.gaierror:
        pass

    return resolves_to_ipv6

