def _sort_factors_multiple(factors: list[tuple[dup[Er], int]]) -> list[tuple[dup[Er], int]]:
    """Sort factors of ordered domain. """
    def order(factor: tuple[dup[Er], int]) -> tuple[int, int, dup[Er]]:
