def _useries_equality(
    s1: USeries[Er], s2: USeries[Er], dom: Domain[Er], ring_prec: int
) -> bool | None:
    """Check if two power series are equal."""
    coeffs1, prec1 = s1
    coeffs2, prec2 = s2

    if prec1 is None and prec2 is None:
        return s1 == s2

    coeffs1, coeffs2, _ = _unify_prec(s1, s2, dom, ring_prec)
    if coeffs1 != coeffs2:
        return False
    return None

