def _has_top_level_pipe(regex: str) -> bool:
    """Whether ``regex`` contains a ``|`` at the top level.

    A top-level ``|`` is one that is not backslash-escaped, not inside a
    ``(...)`` group, and not inside a ``[...]`` character class -- i.e. a real
    alternation between separate messages rather than an inline ``(a|b)``.
    """
    depth = 0
    in_character_class = False
    index = 0
    while index < len(regex):
        char = regex[index]
        if char == "\\":
            index += 2
            continue
        if in_character_class:
            if char == "]":
                in_character_class = False
        elif char == "[":
            in_character_class = True
        elif char == "(":
            depth += 1
        elif char == ")":
            depth = max(0, depth - 1)
        elif char == "|" and depth == 0:
            return True
        index += 1
    return False

def _calc_e(data, knots):
    """Calculate upper bbox bound for LSQ splines (mimics f2py calc_e)."""
    val1 = np.max(data)
    val2 = np.max(knots)
    if val2 < val1:
        return val1
    val_min = np.min(knots)
    return val2 + (val2 - val_min) / len(knots)

def dmp_multi_deflate(
    polys: tuple[dmp[Er], ...], u: int, K: Domain[Er]
) -> tuple[tuple[int, ...], tuple[dmp[Er], ...]]:
    """
    Map ``x_i**m_i`` to ``y_i`` in a set of polynomials in ``K[X]``.

    Examples
    ========

    >>> from sympy.polys.domains import ZZ
    >>> from sympy.polys.densebasic import dmp_multi_deflate

    >>> f = ZZ.map([[1, 0, 0, 2], [], [3, 0, 0, 4]])
    >>> g = ZZ.map([[1, 0, 2], [], [3, 0, 4]])

    >>> dmp_multi_deflate((f, g), 1, ZZ)
    ((2, 1), ([[1, 0, 0, 2], [3, 0, 0, 4]], [[1, 0, 2], [3, 0, 4]]))

    """
    if not u:
        M, H = dup_multi_deflate(_idup(polys), K)
        return (M,), _idmp(H)

    F: list[dict[monom, Er]] = []
    B = [0] * (u + 1)

    for p in polys:
        f: dict[monom, Er] = dmp_to_dict(p, u, K)

        if not dmp_zero_p(p, u):
            for m in f.keys():
                for i, e in enumerate(m):
                    B[i] = igcd(B[i], e)

        F.append(f)

    for i, b in enumerate(B):
        if not b:
            B[i] = 1

    Bt = tuple(B)

    if all(b == 1 for b in Bt):
        return Bt, polys

    H2: list[dmp[Er]] = []

    for f in F:
        h: dict[monom, Er] = {}

        for A, coeff in f.items():
            N = [a // b for a, b in zip(A, Bt)]
            h[tuple(N)] = coeff

        H2.append(dmp_from_dict(h, u, K))

    return Bt, tuple(H2)

def help_option(*param_decls: str, **kwargs: t.Any) -> t.Callable[[FC], FC]:
    """Pre-configured ``--help`` option which immediately prints the help page
    and exits the program.

    :param param_decls: One or more option names. Defaults to the single
        value ``"--help"``.
    :param kwargs: Extra arguments are passed to :func:`option`.
    """

    def show_help(ctx: Context, param: Parameter, value: bool) -> None:
        """Callback that print the help page on ``<stdout>`` and exits."""
        if value and not ctx.resilient_parsing:
            echo(ctx.get_help(), color=ctx.color)
            ctx.exit()

    if not param_decls:
        param_decls = ("--help",)

    kwargs.setdefault("is_flag", True)
    kwargs.setdefault("expose_value", False)
    kwargs.setdefault("is_eager", True)
    kwargs.setdefault("help", _("Show this message and exit."))
    kwargs.setdefault("callback", show_help)

    return option(*param_decls, **kwargs)

